pub fn open_with_operator_task_policy(
        path: &Path,
        settings: Settings,
        workers: usize,
        inputs: crate::operator_task_policy::RestrictedNodeInputs,
    ) -> Result<Self> {
        ensure(
            !settings.app.is_pq_account_profile(),
            "PQ_ACCOUNT_REQUIRES_PQ_NETWORK_OWNER",
        )?;
        let policy = crate::operator_task_policy::authenticate(
            &inputs.raw_policy,
            &inputs.authority,
            crate::operator_task_policy::now_ns().map_err(owner_error)?,
        )
        .map_err(owner_error)?;
        ensure(
            policy.context().network == hex::encode(settings.network())
                && policy.context().parameters == hex::encode(settings.parameters()),
            "OWNER_TASK_CONTEXT",
        )?;
        ensure(
            inputs.pool_permissions.len() <= 64,
            "OWNER_POOL_PERMISSION_LIMIT",
        )?;
        let mut pool_policies = Vec::new();
        for permission in &inputs.pool_permissions {
            let verified = crate::operator_task_policy::pool::authenticate_pool(
                permission,
                &inputs.authority,
                &policy,
                crate::operator_task_policy::now_ns().map_err(owner_error)?,
            )
            .map_err(owner_error)?;
            ensure(
                !pool_policies.iter().any(
                    |p: &std::sync::Arc<crate::operator_task_policy::pool::VerifiedPoolPolicy>| {
                        p.same_operation(&verified)
                    },
                ),
                "OWNER_POOL_DUPLICATE_PERMISSION",
            )?;
            pool_policies.push(std::sync::Arc::new(verified));
        }
        crate::operator_task_policy::verify_catalog(&inputs, &policy).map_err(owner_error)?;
        let expected_marker = policy.marker(&inputs.journal_path).map_err(owner_error)?;
        let journal = crate::operator_task_policy::Journal::open(
            &inputs.journal_path,
            inputs.expected_uid,
            &policy,
        )
        .map_err(owner_error)?;
        if !path.try_exists()? {
            fs::create_dir(path)?;
            fs::set_permissions(path, fs::Permissions::from_mode(0o700))?;
        }
        let meta = fs::symlink_metadata(path)?;
        ensure(
            meta.is_dir()
                && !meta.file_type().is_symlink()
                && meta.uid() == inputs.expected_uid
                && meta.mode() & 0o7777 == 0o700,
            "OWNER_TASK_NAMESPACE",
        )?;
        let marker = path.join("owner-task-policy.required");
        if marker.try_exists()? {
            plain(&marker)?;
            let file = OpenOptions::new()
                .read(true)
                .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
                .open(&marker)?;
            let m = file.metadata()?;
            ensure(
                m.is_file()
                    && m.nlink() == 1
                    && m.uid() == inputs.expected_uid
                    && m.mode() & 0o7777 == 0o600
                    && m.len() == expected_marker.len() as u64,
                "OWNER_TASK_NAMESPACE",
            )?;
            let mut bytes = Vec::new();
            std::io::Read::take(file, expected_marker.len() as u64 + 1).read_to_end(&mut bytes)?;
            ensure(bytes == expected_marker, "OWNER_TASK_NAMESPACE")?;
        } else {
            // No silent migration of an already unrestricted or partially initialized store.
            ensure(
                fs::read_dir(path)?.next().is_none(),
                "OWNER_TASK_FRESH_NAMESPACE_REQUIRED",
            )?;
            let mut file = OpenOptions::new()
                .write(true)
                .create_new(true)
                .mode(0o600)
                .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
                .open(&marker)?;
            file.write_all(&expected_marker)?;
            file.sync_all()?;
            sync_dir(path)?;
        }
        let owner = OwnerPolicy {
            pool_policies,
            epoch: std::sync::Arc::new(std::sync::atomic::AtomicU64::new(1)),
            outside_keys: (
                inputs.authority.registry_key.clone(),
                inputs.authority.task_key.clone(),
            ),
            policy: std::sync::Arc::new(policy),
            required_marker: expected_marker,
            journal: RefCell::new(journal),
            unavailable: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        };
        Self::open_inner(path, settings, workers, None, Some(owner), None, None)
    }
    fn open_inner(
        path: &Path,
        settings: Settings,
        workers: usize,
        hook: Option<&mut Hook<'_>>,
        owner_policy: Option<OwnerPolicy>,
        mining_owner: Option<operator_mining_owner::MiningOwner>,
        continuous_owner: Option<operator_continuous_owner::ContinuousOwner>,
    ) -> Result<Self> {
        Self::open_selected(
            path,
            settings,
            workers,
            hook,
            NativeOwners {
                policy: owner_policy,
                mining: mining_owner,
                continuous: continuous_owner,
                pq_network: None,
                pq_witness: None,
            },
            StateBackend::Legacy,
            false,
        )
    }
    fn open_selected(
        path: &Path,
        settings: Settings,
        workers: usize,
        hook: Option<&mut Hook<'_>>,
        owners: NativeOwners,
        state_backend: StateBackend,
        growth_observation_only: bool,
    ) -> Result<Self> {
        Self::open_selected_mode(
            path,
            settings,
            workers,
            hook,
            owners,
            state_backend,
            SelectedOpen::InitializeOrRecover {
                growth_observation_only,
            },
        )
    }

    fn open_selected_mode(
        path: &Path,
        settings: Settings,
        workers: usize,
        mut hook: Option<&mut Hook<'_>>,
        owners: NativeOwners,
        state_backend: StateBackend,
        selection: SelectedOpen,
    ) -> Result<Self> {
        let (growth_observation_only, existing_owner_only) = match selection {
            SelectedOpen::InitializeOrRecover {
                growth_observation_only,
            } => (growth_observation_only, false),
            SelectedOpen::ExistingPqOwner => (false, true),
        };
        ensure(
            !existing_owner_only
                || matches!(
                    state_backend,
                    StateBackend::PqNetworkV2 | StateBackend::PqWitnessV4
                ),
            "PQ_EXISTING_OWNER_BACKEND",
        )?;
        ensure(
            !authenticated_migration_pending(path)?,
            "NATIVE_STATE_MIGRATION_PENDING",
        )?;
        ensure(
            settings.is_permanent_account_growth_v2()
                == (state_backend == StateBackend::PermanentAccountGrowthV2),
            "GROWTH_PROFILE_BACKEND",
        )?;
        if growth_observation_only {
            ensure(
                state_backend == StateBackend::PermanentAccountGrowthV2
                    && path.join("native.sqlite").is_file(),
                "GROWTH_PACKET_STATUS_EXISTING_STORE_REQUIRED",
            )?;
        }
        let NativeOwners {
            policy: owner_policy,
            mining: mining_owner,
            continuous: continuous_owner,
            pq_network,
            pq_witness,
        } = owners;
        if growth_profile_v2::enabled(&settings.app) {
            ensure(
                state_backend == StateBackend::Legacy,
                "GROWTH_REFERENCE_BACKEND",
            )?;
            ensure(
                owner_policy.is_none() && mining_owner.is_none() && continuous_owner.is_none(),
                "GROWTH_REFERENCE_OWNER",
            )?;
        }

        let pq_selected = matches!(
            state_backend,
            StateBackend::PqNetworkV2 | StateBackend::PqContinuousV3 | StateBackend::PqWitnessV4
        );

pub fn open_with_operator_mining_task_view(
        path: &Path,
        settings: Settings,
        workers: usize,
        inputs: policy::Inputs,
        cpu: &ServiceMutationCpuDomain,
    ) -> Result<Self> {
        ensure(
            !settings.app.is_pq_account_profile(),
            "PQ_ACCOUNT_REQUIRES_PQ_NETWORK_OWNER",
        )?;
        let (owner, permit, operation, fault) = Self::prepare_mining_owner(&inputs, cpu)?;
        Self::finish_mining_open(
            path, settings, workers, &inputs, owner, permit, operation, fault,
        )
    }
    /// Protected finite controller: signatures/latest and a durable startup
    /// reservation precede every complete source material read or Settings replay.
    /// Exact original bootstrap/tile Settings methods are used without adapters.
    pub fn open_operator_mining_checkpoint(
        path: &Path,
        inputs: policy::Inputs,
        cpu: &ServiceMutationCpuDomain,
    ) -> Result<(Self, Vec<u8>, Vec<u8>)> {
        let (owner, permit, operation, mut fault) = Self::prepare_mining_owner(&inputs, cpu)?;
        let build = (|| -> Result<(Settings, Vec<u8>, Vec<u8>)> {
            let catalog = owner
                .catalog
                .as_ref()
                .ok_or("OWNER_MINING_CATALOG_REQUIRED")?;
            let progress = || -> Result<()> {
                permit.progress().map_err(mining_error)?;
                operation.checkpoint()?;
                catalog.ready().map_err(mining_error)
            };
            progress()?;
            let model = catalog
                .read_role("model", 16384, &progress)
                .map_err(mining_error)?;
            let input = catalog
                .read_role("input", 16384, &progress)
                .map_err(mining_error)?;
            let spec_raw = catalog
                .read_role(
                    "spec",
                    crate::operator_checkpoint_tile::SPEC_BYTES as u64,
                    &progress,
                )
                .map_err(mining_error)?;
            let spec =
                crate::operator_checkpoint_tile::OperatorCheckpointTileSpecV1::decode(&spec_raw)?;
            let bundle_raw = catalog
                .read_role("bootstrap", 8192, &progress)
                .map_err(mining_error)?;
            let bundle = crate::operator_deployment::decode(&bundle_raw)?;
            let paths = crate::operator_checkpoint_tile::CheckpointTileRuntimePaths::new(
                catalog.path_role("checkpoint").map_err(mining_error)?,
                catalog.path_role("activation").map_err(mining_error)?,
            );
